def nth_smart_number(n):
    """
    Returns the nth smart number.

    A smart number is a positive integer that can be expressed as the sum of two cubes in two different ways.

    For example, 1 = 0^3 + 1^3 and 1 = 2^3 + 0^3, so 1 is the first smart number.

    The second smart number is 5 = 2^3 + 1^3 and 5 = 1^3 + 4^3, so 5 is the second smart number.

    Similarly, the third smart number is 9 = 3^3 + 0^3 and 9 = 1^3 + 8^3, so 9 is the third smart number.

    Your function should return the nth smart number.

    Input: An integer n >= 1.
    Output: The nth smart number.
    """
    if n == 1:
        return 1

    # Find the cube root of n - 1
    x = int(pow(n - 1, 1 / 3))

    # Check if it’s a perfect cube
    if pow(x, 3) == n - 1:
        # If it is, then we have found a smart number
        return x * (x + 1)

    else:
        # Otherwise, try adding one to the cube root
        y = x + 1
        if pow(y, 3) == n - 1:
            return y * (y + 1)

        # If none of the above work, repeat the process with the next prime number
        return nth_smart_number(n + 1)

