def longest_bitonic_subsequence(arr):
    """
    Given an array of integers, find the length of the longest bitonic subsequence.
    A bitonic sequence is a sequence in which either the elements are strictly increasing,
    or the elements are strictly decreasing.
    """
    if len(arr) < 2:
        return len(arr)

    # Find the longest increasing subsequence
    lis = [0] * len(arr)
    for i in range(1, len(arr)):
        if arr[i] > arr[lis[i-1]]:
            lis[i] = lis[i-1] + 1
        else:
            lis[i] = i

    # Find the longest decreasing subsequence
    lds = [0] * len(arr)
    for i in range(len(arr)-1, -1, -1):
        if arr[i] < arr[lds[i+1]]:
            lds[i] = lds[i+1] + 1
        else:
            lds[i] = i

    # Find the longest bitonic subsequence
    lbs = [0] * len(arr)
    for i in range(len(arr)):
        if arr[i] > arr[lis[i]]:
            lbs[i] = lis[i]
        elif arr[i] < arr[lds[i]]:
            lbs[i] = lds[i]
        else:
            lbs[i] = lis[i] + lds[i] - i

    return max(lbs)

